import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import * as z from "zod";
import Modal from "./Modal";
import Input from "./ui/Input";
import SegmentedControl from "./ui/SegmentedControl";
import { useEffect } from "react";

const customerSchema = z.object({
    name: z.string().min(3, "Nome deve ter pelo menos 3 caracteres"),
    doc: z.string().min(11, "Documento inválido"),
    email: z.string().email("E-mail inválido"),
    phone: z.string().min(8, "Telefone inválido"),
    status: z.enum(["Lead", "Oportunidade", "Ativo", "Vencido", "Arquivado"]),
    origin: z.enum(["Próprio", "Concorrente"]),
    certificate_type: z.string().optional(),
    expiry_date: z.string().optional(),
});

type CustomerFormData = z.infer<typeof customerSchema>;

interface CustomerModalProps {
    isOpen: boolean;
    onClose: () => void;
    onSubmit: (data: CustomerFormData) => void;
    initialData?: any;
    title: string;
}

export default function CustomerModal({ isOpen, onClose, onSubmit, initialData, title }: CustomerModalProps) {
    const {
        register,
        handleSubmit,
        reset,
        setValue,
        watch,
        formState: { errors, isSubmitting }
    } = useForm<CustomerFormData>({
        resolver: zodResolver(customerSchema),
        defaultValues: {
            status: "Lead",
            origin: "Próprio"
        }
    });

    const statusValue = watch("status");
    const originValue = watch("origin");

    useEffect(() => {
        if (initialData) {
            reset({
                ...initialData,
                expiry_date: initialData.expiry_date ? new Date(initialData.expiry_date).toISOString().split('T')[0] : ""
            });
        } else {
            reset({
                name: "",
                doc: "",
                email: "",
                phone: "",
                status: "Lead",
                origin: "Próprio",
                certificate_type: "",
                expiry_date: ""
            });
        }
    }, [initialData, reset, isOpen]);

    return (
        <Modal isOpen={isOpen} onClose={onClose} title={title}>
            <form onSubmit={handleSubmit(onSubmit)} className="space-y-6">
                <div className="p-4 bg-primary/5 dark:bg-white/5 rounded-[2.5rem] border border-primary/10 dark:border-white/10 space-y-5">
                    <SegmentedControl
                        label="Origem do Cliente"
                        value={originValue}
                        onChange={(val) => setValue("origin", val as any)}
                        options={[
                            { label: "Próprio", value: "Próprio" },
                            { label: "Concorrente", value: "Concorrente" }
                        ]}
                    />
                    <SegmentedControl
                        label="Status CRM"
                        value={statusValue}
                        onChange={(val) => setValue("status", val as any)}
                        options={[
                            { label: "Lead", value: "Lead" },
                            { label: "Oportunidade", value: "Oportunidade" },
                            { label: "Ativo", value: "Ativo" }
                        ]}
                    />
                </div>

                <Input
                    label="Nome Completo / Razão Social"
                    {...register("name")}
                    error={errors.name?.message}
                    placeholder="Ex: João Silva ou Empresa LTDA"
                    helpText="Identificação clara agiliza o processo de emissão."
                />

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <Input
                        label="CPF / CNPJ"
                        {...register("doc")}
                        error={errors.doc?.message}
                        placeholder="000.000.000-00"
                    />
                    <Input
                        label="Telefone WhatsApp"
                        {...register("phone")}
                        error={errors.phone?.message}
                        placeholder="(11) 99999-9999"
                        helpText="Lead com WhatsApp tem 40% mais conversão."
                    />
                </div>

                <Input
                    label="E-mail de Faturamento"
                    {...register("email")}
                    error={errors.email?.message}
                    placeholder="exemplo@email.com"
                />

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 p-4 bg-slate-50 dark:bg-slate-900/50 rounded-2xl border border-slate-200 dark:border-slate-800">
                    <Input
                        label="Tipo de Certificado"
                        {...register("certificate_type")}
                        placeholder="Ex: e-CPF A1"
                    />
                    <Input
                        label="Data de Vencimento"
                        type="date"
                        {...register("expiry_date")}
                        helpText={originValue === "Concorrente" ? "Faltando 30 dias vamos te avisar para 'roubar' esse cliente!" : "Aviso automático de renovação."}
                    />
                </div>

                <div className="flex flex-col-reverse md:flex-row items-center justify-end gap-3 pt-6 border-t border-slate-100 dark:border-slate-800/50">
                    <button
                        type="button"
                        onClick={onClose}
                        className="w-full md:w-auto px-8 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest text-slate-500 hover:text-slate-900 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-slate-800 transition-all"
                    >
                        Cancelar
                    </button>
                    <button
                        type="submit"
                        disabled={isSubmitting}
                        className="w-full md:flex-1 md:max-w-xs bg-primary text-white px-8 py-3.5 rounded-2xl font-black text-[10px] uppercase tracking-widest shadow-xl shadow-primary/20 hover:scale-[1.02] active:scale-95 transition-all disabled:opacity-50 disabled:scale-100"
                    >
                        {isSubmitting ? "Sincronizando..." : "Salvar na Máquina de Vendas"}
                    </button>
                </div>
            </form>
        </Modal>
    );
}
